class ConfigmgrApiVertxProxyHandler(private val vertx: Vertx, private val service: ConfigmgrApi, topLevel: Boolean, private val timeoutSeconds: Long) : ProxyHandler() {
    private lateinit var timerID: Long
    private var lastAccessed: Long = 0
    init {
        try {
            this.vertx.eventBus().registerDefaultCodec(ServiceException::class.java,
            ServiceExceptionMessageCodec())
        } catch (ex: IllegalStateException) {}

        if (timeoutSeconds != (-1).toLong() && !topLevel) {
            var period = timeoutSeconds * 1000 / 2
            if (period > 10000) {
                period = 10000
            }
            this.timerID = vertx.setPeriodic(period) { this.checkTimedOut(it) }
        } else {
            this.timerID = -1
        }
        accessed()
    }
    private fun checkTimedOut(id: Long) {
        val now = System.nanoTime()
        if (now - lastAccessed > timeoutSeconds * 1000000000) {
            close()
        }
    }

    override fun close() {
        if (timerID != (-1).toLong()) {
            vertx.cancelTimer(timerID)
        }
        super.close()
    }

    private fun accessed() {
        this.lastAccessed = System.nanoTime()
    }
    override fun handle(msg: Message<JsonObject>) {
        try {
            val json = msg.body()
            val action = msg.headers().get("action") ?: throw IllegalStateException("action not specified")
            accessed()
            val contextSerialized = json.getJsonObject("context") ?: throw IllegalStateException("Received action $action without OperationRequest \"context\"")
            val context = OperationRequest(contextSerialized)
            when (action) {
        
                "adaptiveFormAndInteractiveCommunicationWebChannelConfiguration" -> {
                    val params = context.params
                    val post = ApiHandlerUtils.searchStringInJson(params,"post")?.toBoolean()
                    val apply = ApiHandlerUtils.searchStringInJson(params,"apply")?.toBoolean()
                    val delete = ApiHandlerUtils.searchStringInJson(params,"delete")?.toBoolean()
                    val action = ApiHandlerUtils.searchStringInJson(params,"action")
                    val dollarLocation = ApiHandlerUtils.searchStringInJson(params,"$location")
                    val propertylistParam = ApiHandlerUtils.searchJsonArrayInJson(params,"propertylist")
                    val propertylist:kotlin.Array<kotlin.String>? = if(propertylistParam == null) null
                            else Gson().fromJson(propertylistParam.encode(),
                            , object : TypeToken<kotlin.collections.List<kotlin.String>>(){}.type)
                    val showPlaceholder = ApiHandlerUtils.searchStringInJson(params,"showPlaceholder")?.toBoolean()
                    val maximumCacheEntries = ApiHandlerUtils.searchIntegerInJson(params,"maximumCacheEntries")
                    val afScriptingCompatversion = ApiHandlerUtils.searchStringInJson(params,"af.scripting.compatversion")
                    val makeFileNameUnique = ApiHandlerUtils.searchStringInJson(params,"makeFileNameUnique")?.toBoolean()
                    val generatingCompliantData = ApiHandlerUtils.searchStringInJson(params,"generatingCompliantData")?.toBoolean()
                    GlobalScope.launch(vertx.dispatcher()){
                        val result = service.adaptiveFormAndInteractiveCommunicationWebChannelConfiguration(post,apply,delete,action,dollarLocation,propertylist,showPlaceholder,maximumCacheEntries,afScriptingCompatversion,makeFileNameUnique,generatingCompliantData,context)
                        val payload = JsonObject(Json.encode(result.payload)).toBuffer()
                        val res = OperationResponse(result.statusCode,result.statusMessage,payload,result.headers)
                        msg.reply(res.toJson())
                    }.invokeOnCompletion{
                        it?.let{ throw it }
                    }
                }
        
                "adaptiveFormAndInteractiveCommunicationWebChannelThemeConfigur" -> {
                    val params = context.params
                    val post = ApiHandlerUtils.searchStringInJson(params,"post")?.toBoolean()
                    val apply = ApiHandlerUtils.searchStringInJson(params,"apply")?.toBoolean()
                    val delete = ApiHandlerUtils.searchStringInJson(params,"delete")?.toBoolean()
                    val action = ApiHandlerUtils.searchStringInJson(params,"action")
                    val dollarLocation = ApiHandlerUtils.searchStringInJson(params,"$location")
                    val propertylistParam = ApiHandlerUtils.searchJsonArrayInJson(params,"propertylist")
                    val propertylist:kotlin.Array<kotlin.String>? = if(propertylistParam == null) null
                            else Gson().fromJson(propertylistParam.encode(),
                            , object : TypeToken<kotlin.collections.List<kotlin.String>>(){}.type)
                    val fontListParam = ApiHandlerUtils.searchJsonArrayInJson(params,"fontList")
                    val fontList:kotlin.Array<kotlin.String>? = if(fontListParam == null) null
                            else Gson().fromJson(fontListParam.encode(),
                            , object : TypeToken<kotlin.collections.List<kotlin.String>>(){}.type)
                    GlobalScope.launch(vertx.dispatcher()){
                        val result = service.adaptiveFormAndInteractiveCommunicationWebChannelThemeConfigur(post,apply,delete,action,dollarLocation,propertylist,fontList,context)
                        val payload = JsonObject(Json.encode(result.payload)).toBuffer()
                        val res = OperationResponse(result.statusCode,result.statusMessage,payload,result.headers)
                        msg.reply(res.toJson())
                    }.invokeOnCompletion{
                        it?.let{ throw it }
                    }
                }
        
                "analyticsComponentQueryCacheService" -> {
                    val params = context.params
                    val post = ApiHandlerUtils.searchStringInJson(params,"post")?.toBoolean()
                    val apply = ApiHandlerUtils.searchStringInJson(params,"apply")?.toBoolean()
                    val delete = ApiHandlerUtils.searchStringInJson(params,"delete")?.toBoolean()
                    val action = ApiHandlerUtils.searchStringInJson(params,"action")
                    val dollarLocation = ApiHandlerUtils.searchStringInJson(params,"$location")
                    val propertylistParam = ApiHandlerUtils.searchJsonArrayInJson(params,"propertylist")
                    val propertylist:kotlin.Array<kotlin.String>? = if(propertylistParam == null) null
                            else Gson().fromJson(propertylistParam.encode(),
                            , object : TypeToken<kotlin.collections.List<kotlin.String>>(){}.type)
                    val cqAnalyticsComponentQueryCacheSize = ApiHandlerUtils.searchIntegerInJson(params,"cq.analytics.component.query.cache.size")
                    GlobalScope.launch(vertx.dispatcher()){
